mapper.select:
select id, event_id, channel, receiver, user_id, status, retry_count,
       error_message, created_at, updated_at
from pcd_notification_send_log_table
where event_id = #{eventId}
  and channel = #{channel}
  and receiver = #{receiver}
limit 1;

mapper.update:
update pcd_notification_send_log_table
set status = 'SUCCESS',
    updated_at = now()
where event_id = #{eventId}
  and channel = #{channel}
  and receiver = #{receiver};

update pcd_notification_send_log_table
set status = 'FAILED',
    error_message = #{errorMessage},
    retry_count = retry_count + 1,
    updated_at = now()
where event_id = #{eventId}
  and channel = #{channel}
  and receiver = #{receiver};

update pcd_notification_send_log_table
set status = 'PENDING',
    updated_at = now()
where event_id = #{eventId}
  and channel = #{channel}
  and receiver = #{receiver};
